    df['RSI_4'] = df['close'].diff().rolling(window=4).apply(lambda x: 100 - 100 / (1 + (x[x > 0].mean() / x[x < 0].mean()))).fillna(0)

    # Initialize warm-up flag
    warm_up = True

    # Iterate over the DataFrame
    for i in range(len(df)):
