            if i >= 59 and i >= 3:
                warm_up = False
                if df['close'][i] > df['SMA_60'][i] and df['RSI_4'][i] < 40:
                    position[i] = 1
            else:
                position[i] = 0
        else:
            # Check for exit conditions
            if df['RSI_4'][i] > 55 or df['close'][i] < df['SMA_60'][i]:
                position[i] = 0
            else:
                position[i] = position[i-1]

