def generate_signals(df: pd.DataFrame) -> pd.Series:
    # Initialize the signals series with zeros
    signals = pd.Series(0, index=df.index)

    # Initialize the peak and trough variables
    peak = np.nan
    trough = np.nan

    # Iterate over the DataFrame
    for i in range(len(df)):
        if i < 10:
            # Warm-up period, stay flat
            continue

        # Check for entry conditions
        if signals[i-1] == 0:
            if df['close'].iloc[i] > df['close'].iloc[i-10:i].max():
                signals[i] = 1
                peak = df['close'].iloc[i]
            elif df['close'].iloc[i] < df['close'].iloc[i-10:i].min():
                signals[i] = -1
                trough = df['close'].iloc[i]

        # Update peak and trough
        if signals[i] == 1:
            peak = max(peak, df['close'].iloc[i])
        elif signals[i] == -1:
            trough = min(trough, df['close'].iloc[i])

        # Check for exit conditions
        if signals[i] == 1 and df['close'].iloc[i] < peak * (1 - 0.06):
            signals[i] = 0
        elif signals[i] == -1 and df['close'].iloc[i] > trough * (1 + 0.06):
            signals[i] = 0

    return signals

import numpy as np
import pandas as pd

def generate_signals(df: pd.DataFrame) -> pd.Series:
    # Calculate the Simple Moving Average (SMA) of the last 35 closes
    df['SMA_35'] = df['close'].rolling(window=35).mean()

    # Initialize the position series with zeros
    df['position'] = 0

    # Initialize the peak and trough variables
    df['peak'] = np.nan
    df['trough'] = np.nan

    # Iterate over the DataFrame to generate signals
    for i in range(35, len(df)):
        if df['position'].iloc[i-1] == 0:
            # Check for entry signals
            if df['close'].iloc[i] > df['SMA_35'].iloc[i]:
                df['position'].iloc[i] = 1
                df['peak'].iloc[i] = df['close'].iloc[i]
                df['trough'].iloc[i] = df['close'].iloc[i]
            elif df['close'].iloc[i] < df['SMA_35'].iloc[i]:
                df['position'].iloc[i] = -1
                df['peak'].iloc[i] = df['close'].iloc[i]
                df['trough'].iloc[i] = df['close'].iloc[i]

        # Check for exit signals while in a position
        if df['position'].iloc[i] != 0:
            if df['position'].iloc[i] == 1:
                if df['close'].iloc[i] < df['peak'].iloc[i] * (1 - 0.04):
                    df['position'].iloc[i] = 0
            elif df['position'].iloc[i] == -1:
                if df['close'].iloc[i] > df['trough'].iloc[i] * (1 + 0.04):
                    df['position'].iloc[i] = 0

    return df['position']
